import numpy as np # Reconstruct all C3D10 integration-point mechanics without a reduced basis.
EDGES=[(0,1),(1,2),(2,0),(0,3),(1,3),(2,3)] # Use native C3D10 midside ordering.
def tensor(values): # Expand native symmetric tensor components in their documented order.
    result=np.zeros(values.shape[:-1]+(3,3));result[...,0,0]=values[...,0];result[...,1,1]=values[...,1];result[...,2,2]=values[...,2];result[...,0,1]=result[...,1,0]=values[...,3];result[...,0,2]=result[...,2,0]=values[...,4];result[...,1,2]=result[...,2,1]=values[...,5] # Preserve Cauchy stress and plastic metric tensor symmetry.
    return result # Retain all spatial tensor components.
def quadrature(xyz,tet): # Build independent full-order reference derivatives at all real integration points.
    corners=xyz[tet[:,:4]];jac=corners[:,1:]-corners[:,0,None];volume=np.linalg.det(jac)/6.;inv=np.linalg.inv(jac);dL=np.einsum('ij,ejk->eik',np.array([[-1,-1,-1],[1,0,0],[0,1,0],[0,0,1.]]),inv.transpose(0,2,1));bary=np.full((4,4),.138196601125011);np.fill_diagonal(bary,.585410196624968);gradient=[];shape=[] # Express reference coordinates using exact straight-sided quadratic source geometry.
    for L in bary: # Evaluate every native four-point quadrature station.
        g=np.empty((len(tet),10,3));g[:,:4]=(4*L-1)[None,:,None]*dL # Differentiate corner shape functions.
        for j,(a,b) in enumerate(EDGES): g[:,4+j]=4*(L[a]*dL[:,b]+L[b]*dL[:,a]) # Differentiate every midside shape function.
        gradient.append(g);shape.append(np.r_[L*(2*L-1),[4*L[a]*L[b] for a,b in EDGES]]) # Keep corresponding interpolation functions for thermal consistency.
    return np.stack(gradient,axis=1),volume,np.asarray(shape) # Return element-by-quadrature geometry without FE response data.
def physical_metrics(arrays,metadata,states=None): # Evaluate a raw neural or native field with the same unreduced physics reconstruction.
    xyz=arrays['fe_xyz'];tet=arrays['tet'];n=len(xyz);states=np.asarray(arrays['states'] if states is None else states);gradient,volume,shape=quadrature(xyz,tet);fixed=np.zeros((n,3),bool);fixed[metadata['left_nodes'],:]=True;fixed[metadata['right_nodes'],0]=True;rows=[] # Freeze identical original mechanical boundaries for reference and raw neural fields.
    for step,state in enumerate(states): # Audit every complete stage state independently.
        displacement=state[:n,:3];stress=tensor(state[n:,4:10].reshape(len(tet),4,6));F=np.eye(3)+np.einsum('eia,eqib->eqab',displacement[tet],gradient);J=np.linalg.det(F);invF=np.linalg.inv(F);current_gradient=np.einsum('eqia,eqab->eqib',gradient,invF);force_e=np.einsum('eqab,eqib,eq,e->eia',stress,current_gradient,J,volume/4.);force=np.zeros((n,3));np.add.at(force,tet.ravel(),force_e.reshape(-1,3));reaction_norm=max(float(np.linalg.norm(force[fixed])),1.);residual=float(np.linalg.norm(force[~fixed])/reaction_norm) # Integrate true Cauchy stresses on the deformed configuration and retain every free physical DOF.
        P=tensor(state[n:,11:17]);Cpinv=np.eye(3)-2*P;plastic_determinant=np.linalg.det(Cpinv);temperature=state[:n,3];expected_flux=-float(metadata['params'][5])*45.*np.einsum('eqia,ei->eqa',gradient,temperature[tet]);native_flux=state[n:,23:26].reshape(len(tet),4,3);flux_relative=float(np.linalg.norm(expected_flux-native_flux)/max(np.linalg.norm(expected_flux),1.));rows.append({'step':step,'full_mechanical_free_residual_reaction_normalized':residual,'minimum_deformation_J':float(J.min()),'plastic_metric_minimum_eigenvalue':float(np.linalg.eigvalsh(Cpinv).min()),'plastic_isochoric_determinant_max_error':float(np.max(np.abs(plastic_determinant-1.))),'heat_flux_constitutive_relative':flux_relative}) # Verify constitutive heat flux and complete native plastic metric admissibility separately from learned error.
    return {'frames':rows,'max_full_mechanical_residual':max(r['full_mechanical_free_residual_reaction_normalized'] for r in rows),'min_J':min(r['minimum_deformation_J'] for r in rows),'max_heat_flux_constitutive_relative':max(r['heat_flux_constitutive_relative'] for r in rows),'max_plastic_isochoric_error':max(r['plastic_isochoric_determinant_max_error'] for r in rows),'scope':'Unreduced Cauchy-stress force reconstruction and Fourier flux consistency; these do not independently validate the entire constitutive time-update algorithm.'} # Report the actual scope of the independent physical test.
def main(): # Audit a named complete source dataset without editing its original result.
    parser=argparse.ArgumentParser();parser.add_argument('npz');args=parser.parse_args();path=Path(args.npz);arrays=dict(np.load(path));meta=json.loads(path.with_name('metadata.json').read_text());result=physical_metrics(arrays,meta);path.with_name('independent_physics.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k!='frames'},indent=2)) # Save independent diagnostic evidence beside the source data.
